```rust
fn queue_disconnected_command(queued: &mut VecDeque<Command>, command: Command) {
    if command_is_expired(&command) { fail_command(command, "Fleet daemon request timed out while reconnecting"); return; }
    if command.response.is_none()
        && let RequestBody::ResizeTerminal { terminal, .. } = &command.request.body
        && let Some(index) = queued.iter().position(|queued| { queued.response.is_none() && matches!(&queued.request.body, RequestBody::ResizeTerminal { terminal: queued_terminal, .. } if queued_terminal == terminal) })
    { queued.remove(index); }
    queued.push_back(command);
}
```
